def comprimir_repeticiones(texto: str) -> str:
    if not texto:
        return ""

    result = []
    current_char = texto[0]
    count = 1

    for char in texto[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = char
            count = 1
    result.append(f"{current_char}{count}")

    return "".join(result)

def iniciales(nombre: str) -> str:
    words = nombre.split()
    if not words:
        return ""
    return ''.join(word[0].upper() for word in words)

def aplanar(datos: list) -> list:
    result = []
    for element in datos:
        if isinstance(element, (list, tuple)):
            result.extend(aplanar(element))
        else:
            result.append(element)
    return result

def parsear_ventas(texto: str) -> list[dict]:
    import io

    lines = texto.splitlines()
    if not lines:
        return []

    # Check header
    first_line = lines[0].strip()
    if first_line != "fecha,producto,cantidad,precio":
        raise ValueError("Header must be exactly 'fecha,producto,cantidad,precio'")

    rows = []
    for line in lines[1:]:
        stripped = line.strip()
        if not stripped:
            continue

        # Handle quoted fields
        fields = []
        current_field = ""
        in_quotes = False
        i = 0
        while i < len(line):
            char = line[i]
            if char == '"':
                in_quotes = not in_quotes
                i += 1
            elif char == ',' and not in_quotes:
                fields.append(current_field)
                current_field = ""
                i += 1
            else:
                current_field += char
                i += 1
        fields.append(current_field)

        if len(fields) != 4:
            raise ValueError("Each row must have exactly 4 fields")

        fecha, producto, cantidad_str, precio_str = fields

        try:
            cantidad = int(cantidad_str)
        except ValueError:
            raise ValueError("cantidad must be an integer")
        if cantidad < 0:
            raise ValueError("cantidad must be non-negative")

        try:
            precio = float(precio_str)
        except ValueError:
            raise ValueError("precio must be a number")

        rows.append({
            "fecha": fecha,
            "producto": producto,
            "cantidad": cantidad,
            "precio": precio
        })

    return rows

import re
import calendar

def parsear_fecha(texto: str) -> str:
    # Navegar: mapa de nombres de meses a números
    months = {
        'enero': 1, 'febrero': 2, 'marzo': 3, 'abril': 4, 'mayo': 5, 'junio': 6,
        'julio': 7, 'agosto': 8, 'septiembre': 9, 'octubre': 10, 'noviembre': 11, 'diciembre': 12
    }

    def is_valid_date(year: int, month: int, day: int) -> bool:
        """Devuelve True si la fecha es válida."""
        if month < 1 or month > 12:
            return False
        if day < 1:
            return False
        # obtener el número de días máximo en el mes y año
        return day <= calendar.monthrange(year, month)[1]

    # Limpiar espacios al inicio y fin
    texto = texto.strip()

    # Formato 1: AAAA-MM-DD
    if re.match(r'^\d{4}-\d{2}-\d{2}$', texto):
        partes = texto.split('-')
        if len(partes) != 3:
            raise ValueError
        año, mes, día = map(int, partes)
        if not is_valid_date(año, mes, día):
            raise ValueError
        return f"{año:04d}-{mes:02d}-{día:02d}"

    # Formato 2: DD/MM/AAAA
    if re.match(r'^\d{2}/\d{2}/\d{4}$', texto):
        partes = texto.split('/')
        if len(partes) != 3:
            raise ValueError
        día, mes, año = map(int, partes)
        if not is_valid_date(año, mes, día):
            raise ValueError
        return f"{año:04d}-{mes:02d}-{día:02d}"

    # Formato 3: D de MES de AAAA
    partes = texto.split()
    if len(partes) != 5:
        raise ValueError
    if parts[1] != 'de' or parts[3] != 'de':
        raise ValueError
    try:
        día = int(partes[0])
        mes_nombre = partes[2].lower()
        año = int(partes[4])
    except ValueError:
        raise ValueError
    if mes_nombre not in months:
        raise ValueError
    mes_num = months[mes_nombre]
    if not is_valid_date(año, mes_num, día):
        raise ValueError

    return f"{año:04d}-{mes_num:02d}-{día:02d}"

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado

from typing import List

def mochila(pesos: List[int], valores: List[int], capacidad: int) -> tuple[int, List[int]]:
    # Validate inputs
    if len(pesos) != len(valores):
        raise ValueError("pesos and valores must have the same length")
    if any(p < 0 for p in pesos):
        raise ValueError("pesos cannot be negative")
    if capacidad < 0:
        raise ValueError("capacidad cannot be negative")

    n = len(pesos)

    # If no valid items, return default
    if n == 0:
        return (0, [])

    # Helper to compare solutions according to the criteria
    def better(sol1, sol2):
        value1, indices1 = sol1
        value2, indices2 = sol2
        weight1, weight2 = None, None
        count1, count2 = None, None

        # Calculate total weight and count for each solution
        indices1_list = sorted(indices1)
        indices2_list = sorted(indices2)

        weight1 = sum(pesos[i] for i in indices1_list)
        weight2 = sum(pesos[i] for i in indices2_list)
        count1 = len(indices1_list)
        count2 = len(indices2_list)

        # Compare according to criteria
        if value1 > value2:
            return True
        if value1 < value2:
            return False

        if weight1 < weight2:
            return True
        if weight1 > weight2:
            return False

        if count1 < count2:
            return True
        if count1 > count2:
            return False

        # Lexicographic comparison
        indices1_sorted = sorted(indices1_list)
        indices2_sorted = sorted(indices2_list)
        return indices1_sorted < indices2_sorted

    # Generate all subsets and keep the best one
    best_solution = (0, [])

    # We'll iterate through all subsets using bitmask
    for mask in range(1 << n):
        current_value = 0
        current_indices = []
        current_weight = 0

        for i in range(n):
            if mask & (1 << i):
                current_value += valores[i]
                current_indices.append(i)
                current_weight += pesos[i]

        # Only consider subsets that fit within capacity
        if current_weight <= capacidad:
            # Check if this subset is better than the current best
            current_solution = (current_value, current_indices)
            if better(current_solution, best_solution):
                best_solution = current_solution

    # Edge case: if best_solution is (0, []) but there were items that could be taken
    # We still return (0, []) only if no item was taken at all (weight 0)
    # However, if there are items with positive value that fit, we will have a better solution
    # So we need to check if any item could be taken
    if all(p > capacidad for p in pesos):
        return (0, [])

    return (best_solution[0], best_solution[1])

def evaluar(expresion: str) -> int:
    # Tokenization
    tokens = []
    i = 0
    n = len(expresion)
    while i < n:
        ch = expresion[i]
        if ch == ' ':
            i += 1
            continue
        if ch.isdigit():
            start = i
            while i < n and expresion[i].isdigit():
                i += 1
            tokens.append(expresion[start:i])
            continue
        if ch == '+':
            tokens.append(ch)
            i += 1
        elif ch == '-':
            tokens.append(ch)
            i += 1
        elif ch == '*':
            tokens.append(ch)
            i += 1
        elif ch == '/':
            # Check for '//'
            if i + 1 < n and expresion[i + 1] == '/':
                tokens.append('//')
                i += 2
            else:
                raise ValueError("Invalid operator")
            continue
        elif ch == '(' or ch == ')':
            tokens.append(ch)
            i += 1
            continue
        else:
            raise ValueError("Invalid character")
    if not tokens:
        raise ValueError("Invalid expression")

    # Parser class
    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.index = 0

        def peek(self):
            return self.tokens[self.index] if self.index < len(self.tokens) else None

        def next(self):
            token = self.tokens[self.index]
            self.index += 1
            return token

        def expect(self, expected):
            if self.peek() != expected:
                raise ValueError("Expected " + expected)
            return self.next()

        def parse_expression(self):
            left = self.parse_term()
            while True:
                op = self.peek()
                if op == '+' or op == '-':
                    self.next()
                    right = self.parse_term()
                    if op == '+':
                        left = left + right
                    else:
                        left = left - right
                else:
                    break
            return left

        def parse_term(self):
            left = self.parse_factor()
            while True:
                op = self.peek()
                if op == '*' or op == '//':
                    self.next()
                    right = self.parse_factor()
                    if op == '*':
                        left = left * right
                    else:
                        left = left // right
                else:
                    break
            return left

        def parse_factor(self):
            token = self.peek()
            if token == '-':
                self.next()
                return -self.parse_factor()
            elif token.isdigit():
                return int(token)
            elif token == '(':
                self.next()
                val = self.parse_expression()
                self.expect(')')
                return val
            else:
                raise ValueError("Invalid factor")

    parser = Parser(tokens)
    try:
        result = parser.parse_expression()
        if parser.index != len(tokens):
            raise ValueError("Invalid expression")
        return result
    except ValueError:
        raise
    except ZeroDivisionError:
        raise

from collections import OrderedDict


class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad < 0:
            raise ValueError("La capacidad debe ser no negativa")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave not in self._datos:
            return None
        # Mover el elemento a la end para marcar como usado recientemente
        self._datos.move_to_end(clave)
        return self._datos[clave]

    def put(self, clave, valor):
        if self.capacidad == 0:
            return

        if clave in self._datos:
            # Actualizar valor y mover a end
            self._datos[clave] = valor
            self._datos.move_to_end(clave)
        else:
            # Clave nueva: si la caché está llena, eliminar el elemento LRU
            if len(self._datos) >= self.capacidad:
                self._datos.popitem(last=False)
            self._datos[clave] = valor

    def __len__(self):
        return len(self._datos)
